function CommonLineupCell:Refresh(data)
    local hasData = isNotNull(data)
    
    KTool.SetActive(self.EmptyNode, not hasData)
    KTool.SetActive(self.ContentNode, hasData)
    
    if not hasData then return end

    self.data = data

    local title = data.title
    local teamPower = data.power
    local playerInfo = data.playerInfo
    local team = checkTable(data.team[1])
    local cardsInfo = checkTable(team.cardInfo)
    local catsInfo = checkTable(team.catInfo)

    -- 标题
    if isNotNull(self.Title) then
        CfUtils.FillText(self.Title, title)
    end

    -- 战力
    if isNotNull(self.TeamPower) then
        CfUtils.FillText(self.TeamPower, teamPower)
    end

    -- 玩家信息
    self:RefreshPlayerInfo(playerInfo)

    -- 卡牌编队
    self:RefreshCardsInfo(cardsInfo)

    -- 猫球编队
    self:RefreshCatsInfo(catsInfo)
end

--- 刷新玩家信息
---@param playerInfo any
function CommonLineupCell:RefreshPlayerInfo(playerInfo)
    if isNull(playerInfo) then return end
    if isNull(self.CommonPlayerInfo) then return end

    ---@type CommonPlayerInfo
    local lt = GetLuaBehaviour(self.CommonPlayerInfo.gameObject, "Game.UI.Common.CommonPlayerInfo").Env
    lt:Refresh(playerInfo)
end

--- 刷新卡牌信息
---@param teamInfo any
function CommonLineupCell:RefreshCardsInfo(cardsInfo)
    if IsNull(cardsInfo) then return end
    if isNull(self.UITeamMembersNode) then return end

    local canFormation = false
    local questId = 0
    local teamIndex = 0
    local scale = 0.6

    ---@type UITeamMembersNode
    local lt = GetLuaBehaviour(self.UITeamMembersNode.gameObject, "Game.UI.FightTeam.UITeamMembersNode.UITeamMembersNode").Env
    lt:Refresh(cardsInfo, true, scale, function()
        if canFormation then
            -- print("[异步PVP] 编队", self.component.questId, self.cellIndex)
            UIModule.OpenDialog(
                {id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = questId, teamIndex = teamIndex }}
            )
        end
    end, false, nil, not canFormation, true)
end

--- 刷新猫球信息
---@param catInfo any
function CommonLineupCell:RefreshCatsInfo(catsInfo)
    if isNull(catsInfo) then return end
    if isNull(self.UITeamCatsNode) then return end

    ---@type UIFightTeamCatsNode
    local lt = GetLuaBehaviour(self.UITeamCatsNode.gameObject, "Game.UI.FightTeam.UIFightTeamCatsNode.UIFightTeamCatsNode").Env
    lt:Refresh(catsInfo)
end

return CommonLineupCell